import{_ as e,c as t,o as a,a as n}from"./app.19f3f8f0.js";const m=JSON.parse('{"title":"Content quality checklist for ad review","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Clear company & product story","slug":"_1-clear-company-product-story","link":"#_1-clear-company-product-story","children":[]},{"level":2,"title":"2. Policy documents","slug":"_2-policy-documents","link":"#_2-policy-documents","children":[]},{"level":2,"title":"3. Substantive content","slug":"_3-substantive-content","link":"#_3-substantive-content","children":[]},{"level":2,"title":"4. Trust signals","slug":"_4-trust-signals","link":"#_4-trust-signals","children":[]},{"level":2,"title":"5. Transparent monetization","slug":"_5-transparent-monetization","link":"#_5-transparent-monetization","children":[]}],"relativePath":"blog/policy-and-ads.md"}'),s={name:"blog/policy-and-ads.md"},i=n('<h1 id="content-quality-checklist-for-ad-review" tabindex="-1">Content quality checklist for ad review <a class="header-anchor" href="#content-quality-checklist-for-ad-review" aria-hidden="true">#</a></h1><p>To pass Google Ads / AdMob review, your site and apps should clearly show real user value. Use this checklist before submission.</p><h2 id="_1-clear-company-product-story" tabindex="-1">1. Clear company &amp; product story <a class="header-anchor" href="#_1-clear-company-product-story" aria-hidden="true">#</a></h2><ul><li>Provide About, Services, and Products pages.</li><li>Include real screenshots, feature lists, and store links.</li></ul><h2 id="_2-policy-documents" tabindex="-1">2. Policy documents <a class="header-anchor" href="#_2-policy-documents" aria-hidden="true">#</a></h2><ul><li>Publish privacy policy, terms, and cookie policy.</li><li>Show contact details and who is responsible.</li></ul><h2 id="_3-substantive-content" tabindex="-1">3. Substantive content <a class="header-anchor" href="#_3-substantive-content" aria-hidden="true">#</a></h2><ul><li>Describe features, use cases, and FAQs; maintain at least two blog posts or similar articles.</li></ul><h2 id="_4-trust-signals" tabindex="-1">4. Trust signals <a class="header-anchor" href="#_4-trust-signals" aria-hidden="true">#</a></h2><ul><li>Valid support email, expected response times, and update history (e.g. launch notes).</li></ul><h2 id="_5-transparent-monetization" tabindex="-1">5. Transparent monetization <a class="header-anchor" href="#_5-transparent-monetization" aria-hidden="true">#</a></h2><ul><li>Explain why ads appear and what formats you use (e.g. interstitial, banner) and how you manage frequency.</li></ul><p>This checklist helps address common “thin content” rejection reasons.</p>',13),r=[i];function o(l,c,d,u,h,p){return a(),t("div",null,r)}const y=e(s,[["render",o]]);export{m as __pageData,y as default};
